/*!40000 ALTER TABLE `abt_variabel` DISABLE KEYS */;
REPLACE INTO `abt_variabel` (`no_var`, `nama`, `data_type`, `data_tabel`, `data_kolom`, `urutan_data`, `referensi`, `sql_query`, `default_data`, `multi_sidang`, `locked`, `modifier`, `modified`) VALUES (8521,'PERTIMBANGAN FAKTA HUKUM PERCERAIAN (OTOMATIS) (A-H DAN GABUNGANNYA)','data_sql',NULL,NULL,NULL,NULL,'SELECT\r\n  CASE\r\n    -- A, F, AF, BF, ABF, dan variasinya\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^(\'\r\n                         \'A|a|F|f|\'\r\n                         \'AF|af|Af|aF|FA|Fa|fA|\'\r\n                         \'A dan F|a dan f|A DAN F|a DAN f|A dan f|a dan F|\'\r\n                         \'F dan A|F DAN A|f dan A|\'\r\n                         \'A & F|a & f|A & f|a & F|F & A|F & a|f & A|\'\r\n                         \'BF|bf|FB|fb|\'\r\n                         \'B dan F|b dan f|B Dan F|b Dan f|B dan F|b dan f|\'\r\n                         \'B & F|b & f|B & f|b & F|\'\r\n                         \'ABF|AFB|BAF|BFA|FAB|FBA|\'\r\n                         \'A DAN B DAN F|a dan b dan f|\'\r\n                         \'A & B & F|a & b & f|A Dan B Dan F\'\r\n                       \')$\' THEN\r\n      CONCAT(\"Bahwa #0046# dan #0047# telah melangsungkan pernikahan menurut ketentuan agama Islam;\r\nBahwa sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" #0046# dan #0047# sudah sering terjadi pertengkaran dan perselisihan dikarenakan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \";\r\nBahwa #0046# dan #0047# telah berpisah kediaman bersama sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" yang hingga kini sudah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" dan sudah tidak rukun lagi;\r\nBahwa #0046# dan #0047# sudah berusaha untuk dirukunkan kembali namun tidak berhasil;\")\r\n\r\n    -- B saja\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^[Bb]$\' THEN\r\n      CONCAT(\"Bahwa #0046# dan #0047# telah melangsungkan pernikahan menurut ketentuan agama Islam;\r\nBahwa #0046# dan #0047# telah berpisah kediaman bersama sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" yang hingga kini sudah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" dan sudah tidak rukun lagi;\r\nBahwa #0046# dan #0047# sudah berusaha untuk dirukunkan kembali namun tidak berhasil;\")\r\n\r\n    -- Umum: C, D, E, G, H dan setiap gabungan huruf A-H yang belum punya cabang di atas\r\n    WHEN k.sah AND k.hH AND k.mp IS NULL THEN\r\n      \"<mark>TIDAK BENAR QUERY NYA / ALASAN H: AGAMA PIHAK YANG MURTAD BELUM DIUBAH DI SIPP - ubah agama pihak itu di SIPP, lalu muat ulang ABT</mark>\"\r\n    WHEN k.sah THEN\r\n      CONCAT_WS(CHAR(10 USING utf8),\r\n        \"Bahwa #0046# dan #0047# adalah suami istri sah yang telah melangsungkan pernikahan menurut ketentuan agama Islam dan hingga kini belum pernah bercerai;\",\r\n        IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", IF(k.hF, CONCAT(\"Bahwa\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), CONCAT(\" antara #0046# dan #0047# terus-menerus terjadi perselisihan dan pertengkaran dikarenakan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \";\")), CONCAT(\"Bahwa\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), CONCAT(\" rumah tangga #0046# dan #0047# tidak lagi rukun dan harmonis dikarenakan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \";\"))), IF(k.hF, CONCAT(\"Bahwa\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=222 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" antara #0046# dan #0047# terus-menerus terjadi perselisihan dan pertengkaran;\"), NULL)),\r\n        IF(k.hA, IF(TRIM(\"#6000#\") <> \"\", \"Bahwa #0047# mempunyai kebiasaan buruk berupa #6000# yang sukar disembuhkan;\", \"Bahwa #0047# mempunyai kebiasaan buruk yang sukar disembuhkan;\"), NULL),\r\n        IF(k.hB, CONCAT(\"Bahwa #0047# telah meninggalkan #0046#\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" hingga kini\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \" lebih dari 2 (dua) tahun\"), \" berturut-turut tanpa izin #0046# dan tanpa alasan yang sah;\"), NULL),\r\n        IF(k.hC, CONCAT(\"Bahwa setelah perkawinan berlangsung, #0047# telah dijatuhi hukuman penjara 5 (lima) tahun atau hukuman yang lebih berat\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sebagaimana \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \", putusan pidana tersebut telah berkekuatan hukum tetap, dan sejak itu #0046# dan #0047# tidak lagi hidup bersama sebagai suami istri;\"), NULL),\r\n        IF(k.hD, \"Bahwa #0047# telah melakukan kekejaman atau penganiayaan berat terhadap #0046# yang membahayakan keselamatan jiwa dan raga #0046#;\", NULL),\r\n        IF(k.hE, CONCAT(\"Bahwa \", k.sp, \" mendapat cacat badan atau penyakit yang mengakibatkan \", k.sp, \" tidak dapat menjalankan kewajibannya sebagai \", k.sis, \";\"), NULL),\r\n        IF(k.hG, IF(\"#0047#\" = \'Termohon\', \"<mark>PERIKSA: alasan huruf G (suami melanggar taklik talak, Pasal 116 huruf g KHI) hanya dapat diajukan istri; tidak berlaku pada cerai talak</mark>\", \"Bahwa #0047# telah melanggar taklik talak yang diucapkannya sesudah akad nikah;\"), NULL),\r\n        IF(k.hH, CONCAT(\"Bahwa \", k.mp, \" telah keluar dari agama Islam (<i>murtad</i>) dan \", k.pag, IF(TRIM(\"#0227#\") <> \"\", \" sejak tanggal #0227#\", \"\"), \", dan hingga kini tidak kembali memeluk agama Islam;\"), NULL),\r\n        IF(k.hH, \"Bahwa peralihan agama tersebut menyebabkan rumah tangga #0046# dan #0047# tidak rukun lagi;\", NULL),\r\n        IF(NOT k.hB AND (TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\" OR TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\"), CONCAT(\"Bahwa #0046# dan #0047# telah berpisah tempat tinggal\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" hingga kini selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" dan tidak lagi hidup bersama sebagai suami istri;\"), NULL),\r\n        IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=1268 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\"Bahwa \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=1268 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \";\"), \"Bahwa #0046# dan #0047# sudah berusaha untuk dirukunkan kembali namun tidak berhasil;\"))\r\n\r\n    -- Default\r\n    ELSE\r\n      \'<mark>[HURUF ALASAN PERCERAIAN BELUM DIPILIH]</mark>\'\r\n  END AS data\r\nFROM (\r\n  SELECT y.*,\r\n    CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END AS si,\n    -- 28 Okt: pihak yang sakit (huruf E) menurut rincian 5227; bawaan pihak lawan seperti dulu\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN \"#0046#\" ELSE \"#0047#\" END AS sp,\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'suami\' ELSE \'istri\' END) ELSE (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END) END AS sis,\r\n    CASE WHEN y.ag1 <> 1 THEN \"#0046#\" WHEN y.ag2 <> 1 THEN \"#0047#\" END AS mp,\r\n    CASE CASE WHEN y.ag1 <> 1 THEN y.ag1 WHEN y.ag2 <> 1 THEN y.ag2 END WHEN 2 THEN \'memeluk agama Kristen Protestan\' WHEN 3 THEN \'memeluk agama Kristen Katolik\' WHEN 4 THEN \'memeluk agama Budha\' WHEN 5 THEN \'memeluk agama Hindu\' WHEN 7 THEN \'memeluk agama Khonghucu\' ELSE \'memeluk agama lain selain Islam\' END AS pag\r\n  FROM (\r\n    SELECT z.n, z.v5227,\r\n        IF(z.n <> \'\' AND z.n NOT REGEXP \'[^A-H]\', 1, 0) AS sah,\r\n        IF(INSTR(z.n, \'A\') > 0, 1, 0) AS hA,\r\n        IF(INSTR(z.n, \'B\') > 0, 1, 0) AS hB,\r\n        IF(INSTR(z.n, \'C\') > 0, 1, 0) AS hC,\r\n        IF(INSTR(z.n, \'D\') > 0, 1, 0) AS hD,\r\n        IF(INSTR(z.n, \'E\') > 0, 1, 0) AS hE,\r\n        IF(INSTR(z.n, \'F\') > 0, 1, 0) AS hF,\r\n        IF(INSTR(z.n, \'G\') > 0, 1, 0) AS hG,\r\n        IF(INSTR(z.n, \'H\') > 0, 1, 0) AS hH,\r\n        (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag1,\r\n        (SELECT ph.agama_id FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag2\r\n    FROM (SELECT CASE WHEN UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))) IN (\'FASAKH\', \'MURTAD\') THEN \'H\' ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))), \'DAN\', \'\'), \'&\', \'\'), \',\', \'\'), \' \', \'\'), \'+\', \'\'), \'/\', \'\'), \'.\', \'\'), \'-\', \'\') END AS n, IFNULL((SELECT CONVERT(data USING utf8) FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\'), \'\') AS v5227) z\r\n  ) y\r\n) k;\r\n',NULL,NULL,0,'admin','2026-10-30 22:11:00');
REPLACE INTO `abt_variabel` (`no_var`, `nama`, `data_type`, `data_tabel`, `data_kolom`, `urutan_data`, `referensi`, `sql_query`, `default_data`, `multi_sidang`, `locked`, `modifier`, `modified`) VALUES (8522,'PERTIMBANGAN PETITUM BERDASARKAN FAKTA PERCERAIAN (OTOMATIS) (A-H DAN GABUNGANNYA)','data_sql',NULL,NULL,NULL,NULL,'SELECT \r\n  CASE\r\n    -- Hanya AF (dan berbagai variasi penulisan)\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^(AF|af|Af|aF|A dan F|a dan f|A dan f|a dan F|A & F|a & f|A & f|a & F|F & A|f & a|ABF|AFB|BAF|BFA|FAB|FBA|A DAN B DAN F|a dan b dan f|A & B & F|a & b & f|A Dan B Dan F)$\' THEN\r\n      \"Bahwa berdasarkan fakta angka 1, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\r\nBahwa berdasarkan fakta angka 2, perbuatan #6000# yang dilakukan #0047# telah terbukti memicu perselisihan dan pertengkaran yang terus-menerus antara #0046# dan #0047#, sehingga rumah tangga menjadi tidak tenteram dan tujuan perkawinan tidak tercapai. Dalam hal ini, fokus utama #8554# bukanlah untuk menentukan siapa yang salah dan siapa yang benar dalam pertengkaran tersebut, melainkan untuk menilai apakah perkawinan tersebut secara substantif telah pecah dan tidak dapat didamaikan kembali. Sikap ini sejalan dengan kaidah hukum dalam Putusan Mahkamah Agung Republik Indonesia Nomor 38 K/AG/1990, tanggal 5 Oktober 1991, yang menyatakan:\r\n<i>\\\"Kalau Pengadilan telah yakin bahwa perkawinan ini telah pecah, berarti hati kedua belah pihak telah pecah pula, maka terpenuhilah isi Pasal 19 huruf (f) PP No. 9 Tahun 1975.\\\"</i>;\r\nBahwa berdasarkan fakta angka 2 dan 3, pertengkaran antara #0046# dan #0047# telah menyebabkan keduanya pisah tempat tinggal, hal ini merupakan bukti yang kuat bahwa rumah tangga #0046# dan #0047# sudah tidak rukun dan harmonis lagi, sehingga dalam hal ini patut dinyatakan bahwa rumah tangga #0046# dan #0047# tersebut telah retak dan pecah (<i>break down marriage</i>);\r\nBahwa fakta angka 4 menunjukkan antara #0046# dan #0047# sudah tidak saling mencintai lagi sehingga akan sulit untuk disatukan dalam satu ikatan perkawinan, oleh karenanya perceraian dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\"\r\n\r\n    -- Hanya A\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^[Aa]$\' THEN\r\n      CONCAT(\"Bahwa berdasarkan fakta angka 1, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\r\nBahwa berdasarkan fakta angka 2, #0047# terbukti telah melakukan perbuatan #6000# yang telah menjadi kebiasaan yang sukar untuk disembuhkan. Fakta ini terbukti berdasarkan keterangan para saksi #0046# yang di bawah sumpahnya menerangkan bahwa \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", akibat perbuatan #6001# #0047# tersebut, ketenteraman rumah tangga #0046# dan #0047# menjadi goyah dan tujuan perkawinan untuk membentuk keluarga yang sakinah, mawaddah, dan rahmah tidak mungkin lagi dapat tercapai;\r\nBahwa berdasarkan fakta angka 3, karena perbuatan #0047# tersebut, #0046# dan #0047# telah berpisah tempat tinggal sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" hingga #0053# ini diajukan, dan selama itu tidak ada harapan lagi untuk dapat rukun kembali dalam satu rumah tangga, sehingga dalam hal ini patut dinyatakan bahwa rumah tangga #0046# dan #0047# tersebut telah retak dan pecah (<i>break down marriage</i>);\r\nBahwa fakta angka 4 menunjukkan antara #0046# dan #0047# sudah tidak saling mencintai lagi sehingga akan sulit untuk disatukan dalam satu ikatan perkawinan, oleh karenanya perceraian dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\")\r\n\r\n    -- Hanya BF (dan variasi penulisan)\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^(BF|bf|FB|fb|B DAN F|b DAN f|B Dan F|B & F|b & f|BdanF|b&f)$\' THEN\r\n      \"Bahwa berdasarkan fakta angka 1, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\r\nBahwa berdasarkan fakta angka 2 dan 3, pertengkaran antara #0046# dan #0047# telah menyebabkan keduanya pisah tempat tinggal, hal ini merupakan bukti yang kuat bahwa rumah tangga #0046# dan #0047# sudah tidak rukun dan harmonis lagi, sehingga dalam hal ini patut dinyatakan bahwa rumah tangga #0046# dan #0047# tersebut telah retak dan pecah (<i>break down marriage</i>);\r\nBahwa fakta angka 4 menunjukkan antara #0046# dan #0047# sudah tidak saling mencintai lagi sehingga akan sulit untuk disatukan dalam satu ikatan perkawinan, oleh karenanya perceraian dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\"\r\n\r\n    -- Hanya F\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^[Ff]$\' THEN\r\n      \"Bahwa berdasarkan fakta angka 1, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\r\nBahwa berdasarkan fakta angka 2 dan 3, pertengkaran antara #0046# dan #0047# telah menyebabkan keduanya pisah tempat tinggal, hal ini merupakan bukti yang kuat bahwa rumah tangga #0046# dan #0047# sudah tidak rukun dan harmonis lagi, sehingga dalam hal ini patut dinyatakan bahwa rumah tangga #0046# dan #0047# tersebut telah retak dan pecah (<i>break down marriage</i>);\r\nBahwa fakta angka 4 menunjukkan antara #0046# dan #0047# sudah tidak saling mencintai lagi sehingga akan sulit untuk disatukan dalam satu ikatan perkawinan, oleh karenanya perceraian dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\"\r\n\r\n    -- Hanya B\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^[Bb]$\' THEN\r\n      CONCAT(\"Bahwa berdasarkan fakta angka 1, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\r\nBahwa berdasarkan fakta angka 2, secara eksplisit menunjukkan bahwa rumah tangga #0046# dengan #0047# telah tidak berjalan dengan rukun dan harmonis hingga keduanya telah berpisah tempat tinggal sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" yang lalu;\r\nBahwa fakta angka 3 menunjukkan antara #0046# dan #0047# sudah tidak saling mencintai lagi sehingga akan sulit untuk disatukan dalam satu ikatan perkawinan, oleh karenanya perceraian dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\")\r\n\r\n    -- Umum: C, D, E, G, H dan setiap gabungan huruf A-H yang belum punya cabang di atas\r\n    WHEN k.sah AND k.hH AND k.mp IS NULL THEN\r\n      \"<mark>TIDAK BENAR QUERY NYA / ALASAN H: AGAMA PIHAK YANG MURTAD BELUM DIUBAH DI SIPP - ubah agama pihak itu di SIPP, lalu muat ulang ABT</mark>\"\r\n    WHEN k.sah THEN\r\n      CONCAT_WS(CHAR(10 USING utf8),\r\n        \"Bahwa berdasarkan fakta hukum tersebut, pernikahan antara #0046# dan #0047# dilaksanakan menurut ketentuan hukum Islam, oleh karenanya proses perceraian antara #0046# dan #0047# dapat diperiksa dan diadili di Pengadilan Agama <i>in casu</i> #8008#;\",\r\n        IF(k.hA, CONCAT(\"Bahwa Pasal 19 huruf (a) Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf (a) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena salah satu pihak berbuat zina atau menjadi pemabuk, pemadat, penjudi, dan lain sebagainya yang sukar disembuhkan. Berdasarkan fakta hukum tersebut, #0047# terbukti mempunyai kebiasaan buruk\", IF(TRIM(\"#6000#\") <> \"\", \" berupa #6000#\", \"\"), \" yang sukar disembuhkan, sehingga ketenteraman rumah tangga #0046# dan #0047# menjadi goyah dan alasan tersebut telah terpenuhi;\"), NULL),\r\n        IF(k.hB, CONCAT(\"Bahwa Pasal 19 huruf (b) Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf (b) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena salah satu pihak meninggalkan pihak lain selama 2 (dua) tahun berturut-turut tanpa izin pihak lain dan tanpa alasan yang sah atau karena hal lain di luar kemampuannya. Berdasarkan fakta hukum tersebut, #0047# telah meninggalkan #0046#\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \" lebih dari 2 (dua) tahun\"), \" berturut-turut tanpa izin dan tanpa alasan yang sah, sehingga alasan tersebut telah terpenuhi;\"), NULL),\r\n        IF(k.hC, \"Bahwa Pasal 19 huruf (c) Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf (c) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena salah satu pihak mendapat hukuman penjara 5 (lima) tahun atau hukuman yang lebih berat setelah perkawinan berlangsung, sehingga unsur-unsur yang harus dibuktikan adalah: (1) salah satu pihak mendapat hukuman penjara, (2) hukuman tersebut 5 (lima) tahun atau lebih berat, dan (3) hukuman tersebut dijatuhkan setelah perkawinan berlangsung;\", NULL),\r\n        IF(k.hC, CONCAT(\"Bahwa untuk membuktikan alasan tersebut, Pasal 74 Undang-Undang Nomor 7 Tahun 1989 tentang Peradilan Agama sebagaimana telah diubah dengan Undang-Undang Nomor 3 Tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 <i>jo.</i> Pasal 135 Kompilasi Hukum Islam menentukan bahwa sebagai bukti cukup disampaikan salinan putusan pengadilan yang memutus perkara pidana tersebut disertai keterangan yang menyatakan bahwa putusan itu telah mempunyai kekuatan hukum tetap\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\", dan bukti demikian telah diajukan #0046# berupa salinan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \";\"), \";\")), NULL),\r\n        IF(k.hC, CONCAT(\"Bahwa berdasarkan fakta hukum tersebut, setelah perkawinan berlangsung #0047# telah dijatuhi hukuman penjara 5 (lima) tahun atau hukuman yang lebih berat\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sebagaimana \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" yang telah berkekuatan hukum tetap, sehingga ketiga unsur tersebut telah terpenuhi. Keadaan tersebut membuat #0047# tidak dapat menjalankan kewajibannya sebagai \", k.si, \" dan tidak dapat hidup bersama #0046# dalam waktu yang lama, sehingga tujuan perkawinan untuk membentuk rumah tangga yang bahagia dan kekal sebagaimana dimaksud Pasal 1 Undang-Undang Nomor 1 Tahun 1974 <i>jo.</i> Pasal 3 Kompilasi Hukum Islam tidak dapat terwujud;\"), NULL),\r\n        IF(k.hD, \"Bahwa Pasal 19 huruf (d) Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf (d) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena salah satu pihak melakukan kekejaman atau penganiayaan berat yang membahayakan pihak lain, sehingga unsur-unsur yang harus dibuktikan adalah: (1) adanya perbuatan kekejaman atau penganiayaan berat, (2) perbuatan tersebut dilakukan oleh salah satu pihak terhadap pihak lainnya, dan (3) perbuatan tersebut membahayakan pihak lain;\", NULL),\r\n        IF(k.hD, CONCAT(\"Bahwa berdasarkan fakta hukum tersebut, #0047# telah melakukan kekejaman atau penganiayaan berat terhadap #0046#\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\", yaitu \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \",\"), \"\"), \" yang membahayakan keselamatan jiwa dan raga #0046#, sehingga ketiga unsur tersebut telah terpenuhi;\"), NULL),\r\n        IF(k.hD, \"Bahwa perbuatan tersebut bertentangan dengan kewajiban suami istri untuk saling mencintai, hormat-menghormati, setia, dan memberi bantuan lahir batin yang satu kepada yang lain sebagaimana dimaksud Pasal 33 Undang-Undang Nomor 1 Tahun 1974 <i>jo.</i> Pasal 77 ayat (2) Kompilasi Hukum Islam, serta termasuk kekerasan fisik dalam rumah tangga yang dilarang oleh Pasal 5 huruf a <i>jo.</i> Pasal 6 Undang-Undang Nomor 23 Tahun 2004 tentang Penghapusan Kekerasan dalam Rumah Tangga, sehingga mempertahankan perkawinan dalam keadaan demikian justru membahayakan #0046#;\", NULL),\r\n        IF(k.hE, \"Bahwa Pasal 19 huruf (e) Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf (e) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena salah satu pihak mendapat cacat badan atau penyakit dengan akibat tidak dapat menjalankan kewajibannya sebagai suami atau istri, sehingga unsur-unsur yang harus dibuktikan adalah: (1) salah satu pihak mendapat cacat badan atau penyakit, dan (2) cacat badan atau penyakit tersebut mengakibatkan yang bersangkutan tidak dapat menjalankan kewajibannya sebagai suami atau istri;\", NULL),\r\n        IF(k.hE, CONCAT(\"Bahwa berdasarkan fakta hukum tersebut, \", k.sp, \" mendapat cacat badan atau penyakit\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\", yaitu \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \",\"), \"\"), \" yang mengakibatkan \", k.sp, \" tidak dapat menjalankan kewajibannya sebagai \", k.sis, IF(k.sis = \"suami\", \" sebagaimana dimaksud Pasal 34 ayat (1) Undang-Undang Nomor 1 Tahun 1974 <i>jo.</i> Pasal 80 Kompilasi Hukum Islam\", \" sebagaimana dimaksud Pasal 34 ayat (2) Undang-Undang Nomor 1 Tahun 1974 <i>jo.</i> Pasal 83 Kompilasi Hukum Islam\"), \", sehingga kedua unsur tersebut telah terpenuhi;\"), NULL),\r\n        IF(k.hE AND k.sp = \"#0047#\" AND k.si = \"suami\", \"Bahwa meskipun Pasal 75 Undang-Undang Nomor 7 Tahun 1989 tentang Peradilan Agama sebagaimana telah diubah dengan Undang-Undang Nomor 3 Tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 memberi wewenang kepada Hakim untuk memerintahkan tergugat memeriksakan diri kepada dokter, oleh karena #0047# tidak pernah hadir di persidangan, #8554# menilai keadaan tersebut berdasarkan keterangan para saksi yang saling bersesuaian dan alat bukti lain yang diajukan #0046#;\", NULL),\r\n        IF(k.hE AND k.sp = \"#0046#\", \"Bahwa meskipun Pasal 75 Undang-Undang Nomor 7 Tahun 1989 tentang Peradilan Agama sebagaimana telah diubah terakhir dengan Undang-Undang Nomor 50 Tahun 2009 sejatinya memberi wewenang kepada Hakim untuk memerintahkan pihak yang bersangkutan untuk memeriksakan diri kepada dokter, #8554# menilai bahwa kondisi atau keadaan cacat badan atau penyakit pada diri #0046# tersebut tetap dapat dipertimbangkan dan dibuktikan secara sah melalui persesuaian keterangan para saksi serta alat bukti lain yang diajukan di persidangan;\", NULL),\n        IF(k.hF, CONCAT(\"Bahwa berdasarkan fakta hukum tersebut, antara #0046# dan #0047# telah terjadi perselisihan dan pertengkaran terus-menerus\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" yang disebabkan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" hingga keduanya berpisah tempat tinggal\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \" dan tidak ada harapan akan hidup rukun lagi dalam rumah tangga, sehingga alasan\", IF(k.nkhi > 1, \" perceraian\", \"\"), \" sebagaimana dimaksud Pasal 19 huruf \", k.lpp, \" Peraturan Pemerintah Nomor 9 Tahun 1975 <i>jo.</i> Pasal 116 huruf \", k.lkhi, \" Kompilasi Hukum Islam telah terpenuhi\", IF(k.nkhi > 1, \" secara kumulatif\", \"\"), \";\"), NULL),\r\n        IF(k.hF, \"Bahwa dalam hal ini, fokus utama #8554# bukanlah untuk menentukan siapa yang salah dan siapa yang benar dalam pertengkaran tersebut, melainkan untuk menilai apakah perkawinan tersebut secara substantif telah pecah dan tidak dapat didamaikan kembali. Sikap ini sejalan dengan kaidah hukum dalam Putusan Mahkamah Agung Republik Indonesia Nomor 38 K/AG/1990, tanggal 5 Oktober 1991, yang menyatakan: <i>\\\"Kalau Pengadilan telah yakin bahwa perkawinan ini telah pecah, berarti hati kedua belah pihak telah pecah pula, maka terpenuhilah isi Pasal 19 huruf (f) PP No. 9 Tahun 1975.\\\"</i>;\", NULL),\r\n        IF(k.hG, IF(\"#0047#\" = \'Termohon\', \"<mark>PERIKSA: alasan huruf G (suami melanggar taklik talak, Pasal 116 huruf g KHI) hanya dapat diajukan istri; tidak berlaku pada cerai talak</mark>\", \"Bahwa Pasal 116 huruf (g) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena suami melanggar taklik talak. Berdasarkan fakta hukum tersebut, #0047# telah melanggar taklik talak yang diucapkannya sesudah akad nikah, sehingga alasan tersebut telah terpenuhi;\"), NULL),\r\n        IF(k.hH, \"Bahwa Pasal 116 huruf (h) Kompilasi Hukum Islam menentukan bahwa perceraian dapat terjadi karena peralihan agama atau murtad yang menyebabkan terjadinya ketidakrukunan dalam rumah tangga, sehingga unsur-unsur yang harus dibuktikan adalah: (1) salah satu pihak beralih agama atau murtad, dan (2) peralihan agama tersebut menyebabkan terjadinya ketidakrukunan dalam rumah tangga;\", NULL),\r\n        IF(k.hH, CONCAT(\"Bahwa berdasarkan fakta hukum tersebut, \", k.mp, \" telah keluar dari agama Islam (<i>murtad</i>) dan \", k.pag, IF(TRIM(\"#0227#\") <> \"\", \" sejak tanggal #0227#\", \"\"), \", dan sampai putusan ini diucapkan \", k.mp, \" tidak kembali memeluk agama Islam dan tetap dalam kemurtadannya, sehingga unsur pertama telah terpenuhi;\"), NULL),\r\n        IF(k.hH, CONCAT(\"Bahwa peralihan agama tersebut telah menyebabkan rumah tangga #0046# dan #0047# tidak rukun lagi\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\", terbukti keduanya telah berpisah tempat tinggal selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \", sehingga unsur kedua telah terpenuhi pula;\"), NULL),\r\n        IF(k.hH, CONCAT(\"Bahwa selain itu, Pasal 40 huruf c dan Pasal 44 Kompilasi Hukum Islam melarang perkawinan antara orang Islam dengan orang yang tidak beragama Islam, sejalan dengan firman Allah SWT dalam Surat Al-Mumtahanah ayat 10 yang menegaskan bahwa perempuan-perempuan mukmin tidak halal bagi orang-orang kafir dan orang-orang kafir tidak halal bagi mereka, serta melarang orang-orang mukmin tetap berpegang pada tali perkawinan dengan perempuan-perempuan kafir, sehingga dengan murtadnya \", k.mp, \" perkawinan #0046# dan #0047# tidak dapat lagi dipertahankan menurut hukum Islam;\"), NULL),\r\n        IF(k.hH, \"Bahwa menurut pendapat Abdul Wahab Khalaf, apabila perkataan <i>fasakh</i> disandarkan kepada nikah, maka ia membawa maksud membatalkan atau membubarkan pernikahan oleh sebab-sebab tertentu yang menghalangi kekalnya perkawinan tersebut (<i>vide</i> Abdul Wahab Khalaf, <i>Ahkam al-Ahwal al-Syakhsiyyah Fii al-Syari\'ati al-Islamiyah</i>, Dar al-Qalam, Quwait, 1990, hlm. 60). Imam Muhammad Abu Zahrah dalam kitabnya <i>Al-Ahwal Al-Syakhsiyyah</i> juga menyebutkan bahwa <i>fasakh</i> hakikatnya adalah sesuatu yang diketahui atau terjadi belakangan, bahwa terdapat sebab yang menghalangi langgengnya perkawinan, atau merupakan konsekuensi dari diketahuinya sesuatu yang mengiringi <i>aqad</i>, yang menjadikan <i>aqad</i> tersebut tidak sah (<i>vide</i> Abu Zahrah, <i>Al-Ahwal Al-Syakhsiyyah</i>, Darul Fikr Al-Arabi, Beirut, 1950, hlm. 324);\", NULL),\r\n        CONCAT(\"Bahwa dengan terbuktinya alasan \", IF(k.hH, \"tersebut\", \"perceraian tersebut\"), \", #0046# dan #0047# sudah tidak mungkin lagi disatukan dalam satu ikatan perkawinan yang bahagia dan kekal, oleh karenanya \", IF(k.hH, \"putusnya perkawinan\", \"perceraian\"), \" dipandang merupakan langkah yang terbaik, karena mempertahankan rumah tangga yang demikian justru mendatangkan mudharat yang lebih besar daripada mashlahatnya, hal ini sejalan dengan maksud Pasal 39 Ayat (2) Undang-Undang Nomor 1 Tahun 1974 serta disebutkan dalam kaidah fikih yang telah diambil alih sebagai pendapat #8554# yaitu :\"))\r\n\r\n    ELSE\r\n      \'<mark>[HURUF ALASAN PERCERAIAN BELUM DIPILIH]</mark>\'\r\n  END AS data\r\nFROM (\r\n  SELECT y.*,\r\n    CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END AS si,\n    -- 28 Okt: pihak yang sakit (huruf E) menurut rincian 5227; bawaan pihak lawan seperti dulu\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN \"#0046#\" ELSE \"#0047#\" END AS sp,\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'suami\' ELSE \'istri\' END) ELSE (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END) END AS sis,\n    IF(y.npp <= 1, y.lpp0, CONCAT(SUBSTRING_INDEX(y.lpp0, \', \', y.npp - 1), IF(y.npp = 2, \' dan \', \', dan \'), SUBSTRING_INDEX(y.lpp0, \', \', -1))) AS lpp,\n    IF(y.nkhi <= 1, y.lkhi0, CONCAT(SUBSTRING_INDEX(y.lkhi0, \', \', y.nkhi - 1), IF(y.nkhi = 2, \' dan \', \', dan \'), SUBSTRING_INDEX(y.lkhi0, \', \', -1))) AS lkhi,\r\n    CASE WHEN y.ag1 <> 1 THEN \"#0046#\" WHEN y.ag2 <> 1 THEN \"#0047#\" END AS mp,\r\n    CASE CASE WHEN y.ag1 <> 1 THEN y.ag1 WHEN y.ag2 <> 1 THEN y.ag2 END WHEN 2 THEN \'memeluk agama Kristen Protestan\' WHEN 3 THEN \'memeluk agama Kristen Katolik\' WHEN 4 THEN \'memeluk agama Budha\' WHEN 5 THEN \'memeluk agama Hindu\' WHEN 7 THEN \'memeluk agama Khonghucu\' ELSE \'memeluk agama lain selain Islam\' END AS pag\r\n  FROM (\r\n    SELECT z.n, z.v5227,\r\n        IF(z.n <> \'\' AND z.n NOT REGEXP \'[^A-H]\', 1, 0) AS sah,\r\n        IF(INSTR(z.n, \'A\') > 0, 1, 0) AS hA,\r\n        IF(INSTR(z.n, \'B\') > 0, 1, 0) AS hB,\r\n        IF(INSTR(z.n, \'C\') > 0, 1, 0) AS hC,\r\n        IF(INSTR(z.n, \'D\') > 0, 1, 0) AS hD,\r\n        IF(INSTR(z.n, \'E\') > 0, 1, 0) AS hE,\r\n        IF(INSTR(z.n, \'F\') > 0, 1, 0) AS hF,\r\n        IF(INSTR(z.n, \'G\') > 0, 1, 0) AS hG,\r\n        IF(INSTR(z.n, \'H\') > 0, 1, 0) AS hH,\n        CONCAT_WS(\', \', IF(INSTR(z.n, \'A\') > 0, \'(a)\', NULL), IF(INSTR(z.n, \'B\') > 0, \'(b)\', NULL), IF(INSTR(z.n, \'C\') > 0, \'(c)\', NULL), IF(INSTR(z.n, \'D\') > 0, \'(d)\', NULL), IF(INSTR(z.n, \'E\') > 0, \'(e)\', NULL), IF(INSTR(z.n, \'F\') > 0, \'(f)\', NULL)) AS lpp0,\n        ((INSTR(z.n, \'A\') > 0) + (INSTR(z.n, \'B\') > 0) + (INSTR(z.n, \'C\') > 0) + (INSTR(z.n, \'D\') > 0) + (INSTR(z.n, \'E\') > 0) + (INSTR(z.n, \'F\') > 0)) AS npp,\n        CONCAT_WS(\', \', IF(INSTR(z.n, \'A\') > 0, \'(a)\', NULL), IF(INSTR(z.n, \'B\') > 0, \'(b)\', NULL), IF(INSTR(z.n, \'C\') > 0, \'(c)\', NULL), IF(INSTR(z.n, \'D\') > 0, \'(d)\', NULL), IF(INSTR(z.n, \'E\') > 0, \'(e)\', NULL), IF(INSTR(z.n, \'F\') > 0, \'(f)\', NULL), IF(INSTR(z.n, \'G\') > 0, \'(g)\', NULL), IF(INSTR(z.n, \'H\') > 0, \'(h)\', NULL)) AS lkhi0,\n        ((INSTR(z.n, \'A\') > 0) + (INSTR(z.n, \'B\') > 0) + (INSTR(z.n, \'C\') > 0) + (INSTR(z.n, \'D\') > 0) + (INSTR(z.n, \'E\') > 0) + (INSTR(z.n, \'F\') > 0) + (INSTR(z.n, \'G\') > 0) + (INSTR(z.n, \'H\') > 0)) AS nkhi,\r\n        (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag1,\r\n        (SELECT ph.agama_id FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag2\r\n    FROM (SELECT CASE WHEN UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))) IN (\'FASAKH\', \'MURTAD\') THEN \'H\' ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))), \'DAN\', \'\'), \'&\', \'\'), \',\', \'\'), \' \', \'\'), \'+\', \'\'), \'/\', \'\'), \'.\', \'\'), \'-\', \'\') END AS n, IFNULL((SELECT CONVERT(data USING utf8) FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\'), \'\') AS v5227) z\r\n  ) y\r\n) k;\r\n',NULL,NULL,0,'admin','2026-10-30 22:11:00');
REPLACE INTO `abt_variabel` (`no_var`, `nama`, `data_type`, `data_tabel`, `data_kolom`, `urutan_data`, `referensi`, `sql_query`, `default_data`, `multi_sidang`, `locked`, `modifier`, `modified`) VALUES (8528,'PERTIMBANGAN ALAT BUKTI SAKSI PERCERAIAN VERSTEK (A-H DAN GABUNGANNYA)','data_sql',NULL,NULL,NULL,NULL,'SELECT CONCAT(IF(k.ns BETWEEN 2 AND 5, \'\', CONCAT(\'<mark>PERIKSA: saksi #0046# tercatat di SIPP \', k.ns, \' orang, pertimbangan di bawah dirumuskan untuk 2 saksi</mark> \')),\r\n  CASE\r\n    -- B dan F\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^(BF|bf|FB|fb|B DAN F|b DAN f|B Dan F|B & F|b & f|B dan F)$\' THEN\r\n      CONCAT(\"Menimbang, bahwa keterangan \", k.ls, \" #0046# mengenai \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", telah pisah kediaman bersama sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", yang meninggalkan kediaman bersama adalah \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=7035 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", sehingga #0046# dan #0047# telah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" serta tidak berkomunikasi lagi, berdasarkan pada peristiwa yang diketahui dan dialami sendiri dan sangat beralasan karena \", k.ks, \" adalah \", k.hub, \" serta keterangan \", k.ks, \" tersebut saling bersesuaian antara satu dengan yang lain, berdasarkan ketentuan Pasal 308 dan Pasal 309 RBg maka secara materil keterangan \", k.ks, \" tersebut harus dinyatakan dapat dipertimbangkan;\")\r\n\r\n    -- A atau F atau kombinasi AF (H pindah ke cabang umum)\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^(A|a|F|f|AF|af|Af|aF|FA|Fa|fA|A dan F|a dan f|A dan f|a dan F|F dan A|F dan a|f dan A|A & F|a & f|A & f|a & F|F & A|F & a|f & A|ABF|AFB|BAF|BFA|FAB|FBA|A DAN B DAN F|a dan b dan f|A & B & F|a & b & f|A Dan B Dan F)$\' THEN\r\n      CONCAT(\"Menimbang, bahwa keterangan \", k.ls, \" #0046# mengenai \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", pisah kediaman bersama antara #0046# dengan #0047# dan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=1268 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", sehingga #0046# dan #0047# telah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" serta tidak berkomunikasi lagi, berdasarkan pada peristiwa yang diketahui dan dialami sendiri dan sangat beralasan karena \", k.ks, \" adalah \", k.hub, \" serta keterangan \", k.ks, \" tersebut saling bersesuaian antara satu dengan yang lain, berdasarkan ketentuan Pasal 308 dan Pasal 309 RBg maka secara materil keterangan \", k.ks, \" tersebut harus dinyatakan dapat dipertimbangkan;\")\r\n\r\n    -- B saja\r\n    WHEN IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\') REGEXP \'^[Bb]$\' THEN\r\n      CONCAT(\"Menimbang, bahwa keterangan \", k.ls, \" #0046# mengenai #0046# dan #0047# telah pisah kediaman bersama sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", yang meninggalkan kediaman bersama adalah \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=7035 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", sehingga #0046# dan #0047# telah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \" serta tidak berkomunikasi lagi, berdasarkan pada peristiwa yang diketahui dan dialami sendiri dan sangat beralasan karena \", k.ks, \" adalah \", k.hub, \" serta keterangan \", k.ks, \" tersebut saling bersesuaian antara satu dengan yang lain, berdasarkan ketentuan Pasal 308 dan Pasal 309 RBg maka secara materil keterangan \", k.ks, \" tersebut harus dinyatakan dapat dipertimbangkan;\")\r\n\r\n    -- Umum: C, D, E, G, H dan setiap gabungan huruf A-H yang belum punya cabang di atas\n    WHEN k.sah AND k.hH AND k.mp IS NULL THEN\n      \"<mark>TIDAK BENAR QUERY NYA / ALASAN H: AGAMA PIHAK YANG MURTAD BELUM DIUBAH DI SIPP - ubah agama pihak itu di SIPP, lalu muat ulang ABT</mark>\"\n    WHEN k.sah THEN\n      CONCAT_WS(CHAR(10),\n        IF(k.hC AND TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\"Menimbang, bahwa #0046# juga mengajukan bukti berupa salinan \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8536 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'), \", bukti mana merupakan akta autentik yang mempunyai kekuatan pembuktian sempurna dan mengikat sebagaimana dimaksud Pasal 285 RBg, dan menurut Pasal 74 Undang-Undang Nomor 7 Tahun 1989 tentang Peradilan Agama sebagaimana telah diubah dengan Undang-Undang Nomor 3 Tahun 2006 dan Undang-Undang Nomor 50 Tahun 2009 <i>jo.</i> Pasal 135 Kompilasi Hukum Islam merupakan bukti yang cukup untuk alasan perceraian karena hukuman penjara, sepanjang disertai keterangan bahwa putusan tersebut telah berkekuatan hukum tetap;\"), NULL),\n        CONCAT(\"Menimbang, bahwa keterangan \", k.ls, \" #0046# mengenai \", CONCAT(IF((k.t1), CONCAT(IF(0 > 0, IF(((k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), IF((k.t2), CONCAT(IF(((k.t1)) > 0, IF(((k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), \"kebiasaan buruk #0047# berupa #6000#\"), \"\"), IF((k.t3), CONCAT(IF(((k.t1) + (k.t2)) > 0, IF(((k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), \"#0047# yang telah menjalani hukuman penjara setelah perkawinan berlangsung\"), \"\"), IF((k.t4), CONCAT(IF(((k.t1) + (k.t2) + (k.t3)) > 0, IF(((k.t5) + (k.t6) + (k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), \"kekejaman atau penganiayaan yang dilakukan #0047# terhadap #0046#\"), \"\"), IF((k.t5), CONCAT(IF(((k.t1) + (k.t2) + (k.t3) + (k.t4)) > 0, IF(((k.t6) + (k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), CONCAT(\"cacat badan atau penyakit yang diderita \", k.sp, \" sehingga tidak dapat menjalankan kewajibannya\")), \"\"), IF((k.t6), CONCAT(IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5)) > 0, IF(((k.t7) + (k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), CONCAT(k.mp, \" yang telah keluar dari agama Islam\")), \"\"), IF((k.t7), CONCAT(IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6)) > 0, IF(((k.t8)) > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), CONCAT(\"pisah kediaman bersama antara #0046# dengan #0047#\", IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\" sejak \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"))), \"\"), IF((k.t8), CONCAT(IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7)) > 0, IF(0 > 0, \", \", IF(((k.t1) + (k.t2) + (k.t3) + (k.t4) + (k.t5) + (k.t6) + (k.t7) + (k.t8)) = 2, \" dan \", \", dan \")), \"\"), IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=1268 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\")), IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", CONCAT(\", sehingga #0046# dan #0047# telah berpisah selama \", IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=9944 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')), \"\"), \", berdasarkan pada peristiwa yang diketahui dan dialami sendiri dan sangat beralasan karena \", k.ks, \" adalah \", k.hub, \" serta keterangan \", k.ks, \" tersebut saling bersesuaian antara satu dengan yang lain, berdasarkan ketentuan Pasal 308 dan Pasal 309 RBg maka secara materil keterangan \", k.ks, \" tersebut harus dinyatakan dapat dipertimbangkan;\"))\n\n    -- Default\r\n    ELSE\r\n      \"<mark>[HURUF ALASAN PERCERAIAN BELUM DIPILIH]</mark>\"\r\n  END) AS data\nFROM (\n  SELECT k0.*,\n    IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", 1, 0) AS t1,\n    IF(k0.hA AND TRIM(\"#6000#\") <> \"\", 1, 0) AS t2,\n    IF(k0.hC, 1, 0) AS t3,\n    IF(k0.hD, 1, 0) AS t4,\n    IF(k0.hE, 1, 0) AS t5,\n    IF(k0.hH, 1, 0) AS t6,\n    IF(k0.hB OR k0.hF OR k0.hH OR k0.hC OR TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=246 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", 1, 0) AS t7,\n    IF(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=1268 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\')) <> \"\", 1, 0) AS t8\n  FROM (\n  SELECT y.*,\n    IF(y.ns BETWEEN 2 AND 5, y.ns, 2) AS ne,\n    ELT(IF(y.ns BETWEEN 2 AND 5, y.ns, 2) - 1, \'saksi 1 dan saksi 2\', \'saksi 1, saksi 2, dan saksi 3\', \'saksi 1, saksi 2, saksi 3, dan saksi 4\', \'saksi 1, saksi 2, saksi 3, saksi 4, dan saksi 5\') AS ls,\n    CONCAT(ELT(IF(y.ns BETWEEN 2 AND 5, y.ns, 2) - 1, \'kedua\', \'ketiga\', \'keempat\', \'kelima\'), \' saksi\') AS ks,\n    IF(y.ns BETWEEN 2 AND 5, CONCAT(REPLACE(SUBSTRING_INDEX(y.gs, \'|\', y.ns - 1), \'|\', \', \'), IF(y.ns > 2, \', dan \', \' dan \'), SUBSTRING_INDEX(y.gs, \'|\', -1)), \"#1241# dan #1242#\") AS hub,\n    CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END AS si,\n    -- 28 Okt: pihak yang sakit (huruf E) menurut rincian 5227; bawaan pihak lawan seperti dulu\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN \"#0046#\" ELSE \"#0047#\" END AS sp,\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'suami\' ELSE \'istri\' END) ELSE (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END) END AS sis,\n    CASE WHEN y.ag1 <> 1 THEN \"#0046#\" WHEN y.ag2 <> 1 THEN \"#0047#\" END AS mp,\n    CASE CASE WHEN y.ag1 <> 1 THEN y.nag1 WHEN y.ag2 <> 1 THEN y.nag2 END WHEN \'Protestan\' THEN \'memeluk agama Kristen Protestan\' WHEN \'Katolik\' THEN \'memeluk agama Kristen Katolik\' WHEN \'Kong Hu Cu\' THEN \'memeluk agama Khonghucu\' WHEN \'Lainnya\' THEN \'memeluk agama lain selain Islam\' ELSE CONCAT(\'memeluk agama \', IFNULL(CASE WHEN y.ag1 <> 1 THEN y.nag1 WHEN y.ag2 <> 1 THEN y.nag2 END, \'lain selain Islam\')) END AS pag\n  FROM (\n    SELECT z.n, z.v5227,\n        IF(z.n <> \'\' AND z.n NOT REGEXP \'[^A-H]\', 1, 0) AS sah,\n        IF(INSTR(z.n, \'A\') > 0, 1, 0) AS hA,\n        IF(INSTR(z.n, \'B\') > 0, 1, 0) AS hB,\n        IF(INSTR(z.n, \'C\') > 0, 1, 0) AS hC,\n        IF(INSTR(z.n, \'D\') > 0, 1, 0) AS hD,\n        IF(INSTR(z.n, \'E\') > 0, 1, 0) AS hE,\n        IF(INSTR(z.n, \'F\') > 0, 1, 0) AS hF,\n        IF(INSTR(z.n, \'G\') > 0, 1, 0) AS hG,\n        IF(INSTR(z.n, \'H\') > 0, 1, 0) AS hH,\n        (SELECT COUNT(*) FROM perkara_pihak5 s WHERE s.saksi_pihak_ke = 1 AND s.perkara_id = \'#perkara_id#\') AS ns,\n        (SELECT GROUP_CONCAT(CONVERT(IFNULL(NULLIF(TRIM(TRAILING \'.\' FROM TRIM(s.keterangan)), \'\'), \'...\') USING utf8) ORDER BY s.urutan, s.id SEPARATOR \'|\') FROM perkara_pihak5 s WHERE s.saksi_pihak_ke = 1 AND s.perkara_id = \'#perkara_id#\') AS gs,\n        (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag1,\n        (SELECT ag.nama FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS nag1,\n        (SELECT ph.agama_id FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag2,\n        (SELECT ag.nama FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS nag2\n    FROM (SELECT CASE WHEN UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))) IN (\'FASAKH\', \'MURTAD\') THEN \'H\' ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))), \'DAN\', \'\'), \'&\', \'\'), \',\', \'\'), \' \', \'\'), \'+\', \'\'), \'/\', \'\'), \'.\', \'\'), \'-\', \'\') END AS n, IFNULL((SELECT CONVERT(data USING utf8) FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\'), \'\') AS v5227) z\n  ) y\n) k0\n) k;\n',NULL,NULL,0,'admin','2026-10-30 22:11:00');
REPLACE INTO `abt_variabel` (`no_var`, `nama`, `data_type`, `data_tabel`, `data_kolom`, `urutan_data`, `referensi`, `sql_query`, `default_data`, `multi_sidang`, `locked`, `modifier`, `modified`) VALUES (8531,'POKOK ALASAN PERCERAIAN (OTOMATIS DARI 8503)','data_sql',NULL,NULL,NULL,NULL,'SELECT\n  CASE\n    -- F saja: kalimat yang dahulu tertanam di blangko [01], dipertahankan\n    WHEN k.n = \'F\' THEN\n      \"Menimbang, bahwa setelah membaca dan meneliti surat #0053# #0046#, maka yang menjadi alasan perceraian dalam #0053# #0046# yang pada pokoknya adalah karena rumah tangga #0046# dan #0047# sering terjadi perselisihan dan pertengkaran secara terus menerus. Atas dasar itu, #0046# mohon agar perkawinannya dengan #0047# dapat diceraikan;\"\n\n    WHEN k.sah AND k.hH AND k.mp IS NULL THEN\n      \"<mark>TIDAK BENAR QUERY NYA / ALASAN H: AGAMA PIHAK YANG MURTAD BELUM DIUBAH DI SIPP - ubah agama pihak itu di SIPP, lalu muat ulang ABT</mark>\"\n    -- Huruf lain dan gabungannya (A-H)\n    WHEN k.sah THEN\n      CONCAT(\"Menimbang, bahwa setelah membaca dan meneliti surat #0053# #0046#, maka yang menjadi alasan perceraian dalam #0053# #0046# yang pada pokoknya adalah karena \", CONCAT(IF((k.hA), CONCAT(IF(0 > 0, IF(((k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), \"#0047# mempunyai kebiasaan buruk yang sukar disembuhkan\"), \"\"), IF((k.hB), CONCAT(IF(((k.hA)) > 0, IF(((k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), \"#0047# telah meninggalkan #0046# selama 2 (dua) tahun berturut-turut tanpa izin dan tanpa alasan yang sah\"), \"\"), IF((k.hC), CONCAT(IF(((k.hA) + (k.hB)) > 0, IF(((k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), \"#0047# mendapat hukuman penjara 5 (lima) tahun atau hukuman yang lebih berat setelah perkawinan berlangsung\"), \"\"), IF((k.hD), CONCAT(IF(((k.hA) + (k.hB) + (k.hC)) > 0, IF(((k.hE) + (k.hF) + (k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), \"#0047# melakukan kekejaman atau penganiayaan berat yang membahayakan #0046#\"), \"\"), IF((k.hE), CONCAT(IF(((k.hA) + (k.hB) + (k.hC) + (k.hD)) > 0, IF(((k.hF) + (k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), CONCAT(k.sp, \" mendapat cacat badan atau penyakit dengan akibat tidak dapat menjalankan kewajibannya sebagai \", k.sis)), \"\"), IF((k.hF), CONCAT(IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE)) > 0, IF(((k.hG) + (k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), \"rumah tangga #0046# dan #0047# sering terjadi perselisihan dan pertengkaran secara terus menerus\"), \"\"), IF((k.hG), CONCAT(IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF)) > 0, IF(((k.hH)) > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), IF(\"#0047#\" = \'Termohon\', \"<mark>PERIKSA: alasan huruf G (suami melanggar taklik talak, Pasal 116 huruf g KHI) hanya dapat diajukan istri; tidak berlaku pada cerai talak</mark>\", \"#0047# melanggar taklik talak\")), \"\"), IF((k.hH), CONCAT(IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG)) > 0, IF(0 > 0, \", \", IF(((k.hA) + (k.hB) + (k.hC) + (k.hD) + (k.hE) + (k.hF) + (k.hG) + (k.hH)) = 2, \" serta \", \", serta \")), \"\"), CONCAT(k.mp, \" telah keluar dari agama Islam (<i>murtad</i>) sehingga rumah tangga #0046# dan #0047# tidak rukun lagi\")), \"\")), \". Atas dasar itu, #0046# mohon agar perkawinannya dengan #0047# dapat \", IF(k.hH, \"difasakhkan;\", \"diceraikan;\"))\n\n    ELSE\n      \"<mark>[HURUF ALASAN PERCERAIAN BELUM DIPILIH]</mark>\"\n  END AS data\nFROM (\n  SELECT y.*,\n    CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END AS si,\n    -- 28 Okt: pihak yang sakit (huruf E) menurut rincian 5227; bawaan pihak lawan seperti dulu\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN \"#0046#\" ELSE \"#0047#\" END AS sp,\n    CASE WHEN y.v5227 REGEXP \'#0046#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0046#\' AND y.v5227 NOT REGEXP \'#0047#( yang| sedang| telah| masih)* (sakit|menderita|mengidap|mengalami (sakit|penyakit|strok|stroke|lumpuh|kelumpuhan|cacat|gangguan|kebutaan)|cacat|lumpuh|buta|terkena|terserang|divonis)|(sakit|penyakit|cacat|lumpuh|strok|stroke|kelumpuhan)(nya)?( yang)?( diderita| dialami| diidap)?( oleh)? #0047#\' THEN (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'suami\' ELSE \'istri\' END) ELSE (CASE WHEN \"#0047#\" = \'Termohon\' THEN \'istri\' ELSE \'suami\' END) END AS sis,\n    CASE WHEN y.ag1 <> 1 THEN \"#0046#\" WHEN y.ag2 <> 1 THEN \"#0047#\" END AS mp,\n    CASE CASE WHEN y.ag1 <> 1 THEN y.nag1 WHEN y.ag2 <> 1 THEN y.nag2 END WHEN \'Protestan\' THEN \'memeluk agama Kristen Protestan\' WHEN \'Katolik\' THEN \'memeluk agama Kristen Katolik\' WHEN \'Kong Hu Cu\' THEN \'memeluk agama Khonghucu\' WHEN \'Lainnya\' THEN \'memeluk agama lain selain Islam\' ELSE CONCAT(\'memeluk agama \', IFNULL(CASE WHEN y.ag1 <> 1 THEN y.nag1 WHEN y.ag2 <> 1 THEN y.nag2 END, \'lain selain Islam\')) END AS pag\n  FROM (\n    SELECT z.n, z.v5227,\n        IF(z.n <> \'\' AND z.n NOT REGEXP \'[^A-H]\', 1, 0) AS sah,\n        IF(INSTR(z.n, \'A\') > 0, 1, 0) AS hA,\n        IF(INSTR(z.n, \'B\') > 0, 1, 0) AS hB,\n        IF(INSTR(z.n, \'C\') > 0, 1, 0) AS hC,\n        IF(INSTR(z.n, \'D\') > 0, 1, 0) AS hD,\n        IF(INSTR(z.n, \'E\') > 0, 1, 0) AS hE,\n        IF(INSTR(z.n, \'F\') > 0, 1, 0) AS hF,\n        IF(INSTR(z.n, \'G\') > 0, 1, 0) AS hG,\n        IF(INSTR(z.n, \'H\') > 0, 1, 0) AS hH,\n        (SELECT ph.agama_id FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag1,\n        (SELECT ag.nama FROM perkara_pihak1 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS nag1,\n        (SELECT ph.agama_id FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS ag2,\n        (SELECT ag.nama FROM perkara_pihak2 pp JOIN pihak ph ON ph.id = pp.pihak_id LEFT JOIN agama ag ON ag.id = ph.agama_id WHERE pp.perkara_id = \'#perkara_id#\' ORDER BY pp.urutan LIMIT 1) AS nag2\n    FROM (SELECT CASE WHEN UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))) IN (\'FASAKH\', \'MURTAD\') THEN \'H\' ELSE REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(UPPER(TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag_g1.abt_data_teks WHERE no_var=8503 AND perkara_id=\'#perkara_id#\') USING utf8),\'\\\\\',\'/\'),\'\"\',\'&quot;\'),\'\'\'\',\'&#39;\'),\'\'))), \'DAN\', \'\'), \'&\', \'\'), \',\', \'\'), \' \', \'\'), \'+\', \'\'), \'/\', \'\'), \'.\', \'\'), \'-\', \'\') END AS n, IFNULL((SELECT CONVERT(data USING utf8) FROM aps_badilag_g1.abt_data_teks WHERE no_var=5227 AND perkara_id=\'#perkara_id#\'), \'\') AS v5227) z\n  ) y\n) k;\n',NULL,NULL,0,'admin','2026-10-30 22:11:00');
